using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable]public sealed class MetaMetrics{public NumberData reward,modelCost;public NumberData[] upgradeCosts;public double analysisSpeed,fabrication,amplifier,core;}
 [Serializable]public sealed class MetaCase{public string name,action,id,amount;public double at;public StateData before,expected;public PrestigeMetrics rates;public MetaMetrics metaRates;}
 [Serializable]public sealed class MetaCases{public string scope;public MetaCase[] cases;}
 public sealed class MetaParityTests
 {
  static void Near(ScientificNumber a,ScientificNumber b,string name){if(b.IsZero)Assert.That(a.IsZero,Is.True,name);else Assert.That(a.Log10(),Is.EqualTo(b.Log10()).Within(2e-10),name);}
  [Test]public void AxiomsModelsPoolSlotsAndCyclesMatchActualTypeScript()
  {var f=JsonUtility.FromJson<MetaCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/MetaReferenceCases.json")));Assert.That(MetaBalance.Axioms.Length,Is.EqualTo(24));Assert.That(MetaBalance.Models.Length,Is.EqualTo(10));foreach(var c in f.cases){var s=c.before.ToState();string original=JsonUtility.ToJson(StateData.From(s));var n=s;switch(c.action){case "axiom-buy":n=MetaRules.Buy(s,c.id);break;case "develop":n=MetaRules.Develop(s);break;case "model-upgrade":n=MetaRules.Upgrade(s,c.id);break;case "model-select":n=MetaRules.Select(s,c.id);break;case "discover":n=s.Copy();PrestigeRules.Discover(n);break;case "axiom-reset":n=MetaRules.AxiomReset(s);break;case "reset":n=PrestigeRules.Reset(s);break;case "earn":n=s.Copy();PrestigeRules.Earn(n,ScientificNumber.Parse(c.amount));break;case "tap":n=Game.Tap(s,s.SavedAt);break;case "train":n=Game.Train(s,c.id);break;case "research":n=Game.Research(s,c.id);break;case "analysis":n=MaterialAnalysis.Start(s,Array.FindIndex(ItemBalance.Analyses,a=>a.Id==c.id));break;case "advance":n=Game.Advance(s,c.at);break;case "analysis-plan":n=MetaAutomation.Analysis(s);break;case "module":n=Workshop.StartModule(s,Array.FindIndex(ItemBalance.Modules,m=>m.Id==c.id));break;case "salvage":n=MetaAutomation.Salvage(s,c.id,double.Parse(c.amount,System.Globalization.CultureInfo.InvariantCulture));break;}
   Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(original),c.name+" pure");PrestigeParityTests.Numbers(n,c.expected,c.name);var e=c.expected.ToState();Assert.That(n.Meta.axioms,Is.EqualTo(e.Meta.axioms),c.name+" axiom levels");Assert.That(n.Meta.models,Is.EqualTo(e.Meta.models),c.name+" model pool");Assert.That(n.Meta.rng,Is.EqualTo(e.Meta.rng),c.name+" RNG");Assert.That(n.Meta.resets,Is.EqualTo(e.Meta.resets),c.name+" axiom cycles");Assert.That(n.Meta.records,Is.EqualTo(e.Meta.records),c.name+" records");Assert.That(n.Meta.tutorial,Is.EqualTo(e.Meta.tutorial),c.name+" Mira state");Assert.That(n.Workshop.activeModel,Is.EqualTo(e.Workshop.activeModel),c.name+" single active");Assert.That(n.Workshop.activeModelLevel,Is.EqualTo(e.Workshop.activeModelLevel),c.name+" active level");Assert.That(ScientificNumber.FromData(n.Meta.available).CompareTo(ScientificNumber.FromData(e.Meta.available)),Is.Zero,c.name+" exact axiom balance");Assert.That(ScientificNumber.FromData(n.Meta.total).CompareTo(ScientificNumber.FromData(e.Meta.total)),Is.Zero,c.name+" total axioms");Near(ScientificNumber.FromData(n.Prestige.knowledge),ScientificNumber.FromData(e.Prestige.knowledge),c.name+" knowledge");Assert.That(n.Meta.passiveRemainders,Is.EqualTo(e.Meta.passiveRemainders).Within(1e-9),c.name+" passive remainders");Assert.That(n.Meta.salvageRemainders,Is.EqualTo(e.Meta.salvageRemainders).Within(1e-9),c.name+" salvage remainders");Assert.That(n.Workshop.hasAnalysis,Is.EqualTo(e.Workshop.hasAnalysis),c.name+" analysis presence");if(n.Workshop.hasAnalysis){Assert.That(n.Workshop.analysis.required,Is.EqualTo(e.Workshop.analysis.required).Within(1e-7),c.name+" paid analysis work");Assert.That(n.Workshop.analysis.done,Is.EqualTo(e.Workshop.analysis.done).Within(1e-7),c.name+" analysis progress");}
   Near(Game.Compute(n),ScientificNumber.FromData(c.rates.compute),c.name+" compute");Near(Game.Income(n),ScientificNumber.FromData(c.rates.income),c.name+" income");Near(Game.DataRate(n),ScientificNumber.FromData(c.rates.dataRate),c.name+" data");Near(PrestigeRules.KnowledgeRate(n),ScientificNumber.FromData(c.rates.knowledgeRate),c.name+" knowledge rate");Near(PrestigeRules.Claim(n),ScientificNumber.FromData(c.rates.claim),c.name+" INT");Assert.That(Game.WorkSpeed(n),Is.EqualTo(c.rates.trainingSpeed).Within(1e-8),c.name+" training");Assert.That(Game.WorkSpeed(n,true),Is.EqualTo(c.rates.researchSpeed).Within(1e-8),c.name+" research");Near(MetaRules.Reward(n),ScientificNumber.FromData(c.metaRates.reward),c.name+" axiom reward");Near(MetaRules.ModelCost(n),ScientificNumber.FromData(c.metaRates.modelCost),c.name+" acquisition price");for(int i=0;i<10;i++)Near(MetaRules.UpgradeCost(n,i),ScientificNumber.FromData(c.metaRates.upgradeCosts[i]),c.name+" upgrade price "+i);Assert.That(MaterialAnalysis.Speed(n),Is.EqualTo(c.metaRates.analysisSpeed).Within(1e-8),c.name+" analysis speed");Assert.That(MetaAutomation.Fabrication(n),Is.EqualTo(c.metaRates.fabrication).Within(1e-10),c.name+" fabrication");Assert.That(Workshop.Amplifier(n),Is.EqualTo(c.metaRates.amplifier).Within(1e-9),c.name+" item amplifier");Assert.That(MetaRules.Core(n),Is.EqualTo(c.metaRates.core).Within(1e-9),c.name+" model core");Game.Validate(n);
  }}
  [Test]public void OnlineOfflineAndReloadDoNotReplayModelRngOrAxiomReset()
  {var s=Game.New(1000);s.Prestige.lab=true;s.Prestige.labSeed=true;s.Prestige.knowledge=ScientificNumber.From(100000).ToData();s=MetaRules.Develop(s);var restored=StateData.From(s).ToState();Assert.That(restored.Meta.rng,Is.EqualTo(s.Meta.rng));var next=MetaRules.Develop(restored);Assert.That(next.Meta.models.Count(l=>l>=0),Is.EqualTo(2));var continuous=Game.Advance(next,61000);var split=Game.Advance(StateData.From(Game.Advance(next,31000)).ToState(),61000);Near(continuous.Credits,split.Credits,"split credits");Near(ScientificNumber.FromData(continuous.Prestige.knowledge),ScientificNumber.FromData(split.Prestige.knowledge),"split knowledge");Assert.That(Game.Advance(continuous,61000),Is.SameAs(continuous));s.Prestige.known=PrestigeBalance.Nodes.Take(30).Select(n=>n.Id).ToArray();s.Prestige.Entitlement=ScientificNumber.From(1e6);long ticket=s.Prestige.revision;var reset=MetaRules.AxiomReset(s,ticket);Assert.That(reset.Meta.resets,Is.EqualTo(1));Assert.That(MetaRules.AxiomReset(StateData.From(reset).ToState(),ticket).Meta.resets,Is.EqualTo(1));}
 }
}
